def gen(rng):
    def tree(n, shape, lo, hi):
        vals = [rng.randint(lo, hi) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        if shape == 'left':
            for i in range(1, n):
                L[i - 1] = i
        elif shape == 'right':
            for i in range(1, n):
                R[i - 1] = i
        elif shape == 'zig':
            for i in range(1, n):
                if i % 2:
                    L[i - 1] = i
                else:
                    R[i - 1] = i
        elif shape == 'complete':
            for i in range(1, n):
                p = (i - 1) // 2
                if i % 2:
                    L[p] = i
                else:
                    R[p] = i
        else:
            slots = [(0, 0), (0, 1)]
            for i in range(1, n):
                k = rng.randrange(len(slots))
                slots[k], slots[-1] = slots[-1], slots[k]
                p, side = slots.pop()
                if side == 0:
                    L[p] = i
                else:
                    R[p] = i
                slots.append((i, 0))
                slots.append((i, 1))
        out = [str(vals[0])]
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            for c in (L[u], R[u]):
                if c == -1:
                    out.append('null')
                else:
                    out.append(str(vals[c]))
                    q.append(c)
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)
